const stats = $('Get Yesterday Stats').item.json.data;
const logs = $('Get Top Logs').item.json.data || [];

// Format report
let report = `📊 รายงานประจำวัน\n`;
report += `วันที่: ${new Date().toLocaleDateString('th-TH')}\n\n`;

// Stats
report += `📈 สถิติรวม:\n`;
report += `• Total Requests: ${stats.total.toLocaleString()}\n`;
report += `• Unique IPs: ${stats.uniqueIPs}\n`;
report += `• GET: ${stats.methods.GET || 0} | POST: ${stats.methods.POST || 0}\n\n`;

// Top URLs
if (stats.topURLs && Object.keys(stats.topURLs).length > 0) {
  report += `🔝 Top URLs:\n`;
  Object.entries(stats.topURLs).slice(0, 5).forEach(([url, count], i) => {
    report += `${i + 1}. ${url} (${count})\n`;
  });
  report += `\n`;
}

// Top Users
if (stats.users && Object.keys(stats.users).length > 0) {
  report += `👥 Top Users:\n`;
  Object.entries(stats.users).slice(0, 5).forEach(([user, count], i) => {
    report += `${i + 1}. ${user} (${count})\n`;
  });
  report += `\n`;
}

// Recent activity
if (logs.length > 0) {
  report += `⏰ กิจกรรมล่าสุด:\n`;
  logs.slice(0, 3).forEach((log, i) => {
    report += `${i + 1}. ${log.method} ${log.url}\n`;
    report += `   IP: ${log.ip} | User: ${log.username}\n`;
  });
}

return [{
  json: {
    report,
    stats
  }
}];
